(()=>{'use strict';
const stems={3:'prop',4:'but',5:'pent',6:'hex'},sub=n=>String(n).replace(/\d/g,x=>'₀₁₂₃₄₅₆₇₈₉'[x]);
const line=n=>Array.from({length:n-1},(_,i)=>[i,i+1]);
function adjacency(n,edges){const a=Array.from({length:n},()=>[]);edges.forEach(([u,v])=>{a[u].push(v);a[v].push(u)});return a;}
function key(n,edges){const a=adjacency(n,edges),visit=(v,p)=>'('+a[v].filter(x=>x!==p).map(x=>visit(x,v)).sort().join('')+')';return a.map((_,i)=>visit(i,-1)).sort()[0];}
const banks={4:[['Butane',line(4)],['2-methylpropane',[[0,1],[1,2],[1,3]]]],5:[['Pentane',line(5)],['2-methylbutane',[[0,1],[1,2],[2,3],[1,4]]],['2,2-dimethylpropane',[[0,1],[1,2],[1,3],[1,4]]]],6:[['Hexane',line(6)],['2-methylpentane',[[0,1],[1,2],[2,3],[3,4],[1,5]]],['3-methylpentane',[[0,1],[1,2],[2,3],[3,4],[2,5]]],['2,2-dimethylbutane',[[0,1],[1,2],[2,3],[1,4],[1,5]]],['2,3-dimethylbutane',[[0,1],[1,2],[2,3],[1,4],[2,5]]]]};
function chainName(n,e){return banks[n].find(x=>key(n,x[1])===key(n,e))?.[0]||'Unknown structure';}
function move(n,e,leaf,target){const a=adjacency(n,e);if(a[leaf].length!==1||leaf===target||a[leaf][0]===target||a[target].length>=4)return null;return e.filter(x=>!x.includes(leaf)).concat([[leaf,target]]);}
function position(n,mode,p){const bond=['ene','yne'].includes(mode),max=bond?n-2:mode==='one'?n-2:n-1,min=mode==='one'?1:0;p=Math.max(min,Math.min(max,p));const loc=bond?Math.min(p+1,n-p-1):Math.min(p+1,n-p);const name=mode==='oh'?`${stems[n]}an-${loc}-ol`:mode==='cl'?`${loc}-chloro${stems[n]}ane`:`${stems[n]}${mode==='one'?'an':''}-${loc}-${mode}`;const h=2*n+(mode==='ene'||mode==='one'?0:mode==='yne'?-2:mode==='cl'?1:2);const formula='C'+sub(n)+'H'+sub(h)+(mode==='cl'?'Cl':['oh','one'].includes(mode)?'O':'');const hydrogens=Array.from({length:n},(_,i)=>i===0||i===n-1?3:2);if(bond){hydrogens[p]-=mode==='ene'?1:2;hydrogens[p+1]-=mode==='ene'?1:2;}else hydrogens[p]-=mode==='one'?2:1;return {p,min,max,loc,name,formula,hydrogens,bond};}
function layout(n,e){const a=adjacency(n,e);let path=[];function walk(v,p,route){const next=[...route,v];if(next.length>path.length)path=next;a[v].filter(x=>x!==p).forEach(x=>walk(x,v,next));}a.forEach((_,i)=>walk(i,-1,[]));const pts=[],dx=90,start=(700-(path.length-1)*dx)/2;path.forEach((v,i)=>pts[v]=[start+i*dx,205]);path.forEach(v=>{a[v].filter(x=>!path.includes(x)).forEach((x,j)=>pts[x]=[pts[v][0],205+(j%2?-100:100)]);});return pts;}
if(typeof module!=='undefined'&&module.exports)module.exports={banks,key,move,chainName,position,adjacency,layout};if(typeof document==='undefined')return;
const $=id=>document.getElementById(id),ln=(a,b,order=1,color='#7f9770')=>Array.from({length:order},(_,i)=>{const d=(i-(order-1)/2)*7;return `<line x1="${a[0]}" y1="${a[1]+d}" x2="${b[0]}" y2="${b[1]+d}" stroke="${color}" stroke-width="4"/>`}).join('');
function atom(x,y,label,extra=''){return `<g ${extra}><circle cx="${x}" cy="${y}" r="25"/><text x="${x}" y="${y+6}" text-anchor="middle">${label}</text></g>`;}
function mountPosition(){if(!$('pos-game'))return;let n=4,mode='oh',p=0,showH=false,pinned=null;const board=$('pos-board');
function drawing(state){const r=position(state.n,state.mode,state.p),pts=Array.from({length:state.n},(_,i)=>[350+(i-(state.n-1)/2)*90,225]);let s='';for(let i=0;i<state.n-1;i++)s+=ln(pts[i],pts[i+1],r.bond&&i===r.p?(state.mode==='ene'?2:3):1,r.bond&&i===r.p?'#bb655c':'#7f9770');if(!r.bond){const a=pts[r.p],b=[a[0],115];s+=ln(a,b,state.mode==='one'?2:1,'#bb655c');s+=atom(...b,state.mode==='oh'?'OH':state.mode==='cl'?'Cl':'O','class="si-feature"');}pts.forEach((a,i)=>{s+=atom(...a,showH?'C'+(r.hydrogens[i]?'H'+(r.hydrogens[i]>1?sub(r.hydrogens[i]):''):''):'C');s+=`<text x="${a[0]}" y="274" text-anchor="middle" class="si-index">${i+1}</text>`;});const cx=r.bond?(pts[r.p][0]+pts[r.p+1][0])/2:pts[r.p][0],cy=r.bond?225:115;s+=`<ellipse cx="${cx}" cy="${cy}" rx="${r.bond?70:38}" ry="38" class="si-handle"/>`;return s;}
function render(){const r=position(n,mode,p);p=r.p;board.innerHTML=drawing({n,mode,p});$('pos-name').textContent=r.name;$('pos-formula').textContent=r.formula;$('pos-slider').min=r.min+1;$('pos-slider').max=r.max+1;$('pos-slider').value=p+1;$('pos-location').textContent='Position '+(p+1);$('pos-prev').disabled=p===r.min;$('pos-next').disabled=p===r.max;$('pos-status').textContent=pinned?(pinned.name===r.name?'Same compound as the pinned structure.':'Different position isomer; same molecular formula.') :'';$('pos-comparison').hidden=!pinned;}
function clearPin(){pinned=null;}
$('pos-count').addEventListener('change',e=>{n=+e.target.value;p=0;clearPin();render()});$('pos-mode').addEventListener('change',e=>{mode=e.target.value;p=0;clearPin();render()});$('pos-slider').addEventListener('input',e=>{p=+e.target.value-1;render()});$('pos-prev').addEventListener('click',()=>{p--;render()});$('pos-next').addEventListener('click',()=>{p++;render()});$('pos-h').addEventListener('click',()=>{showH=!showH;$('pos-h').setAttribute('aria-pressed',showH);if(pinned)$('pos-pinned-board').innerHTML=drawing(pinned);render()});$('pos-pin').addEventListener('click',()=>{pinned={n,mode,p,name:position(n,mode,p).name};$('pos-pinned-board').innerHTML=drawing(pinned);$('pos-pinned-name').textContent=pinned.name;render()});let dragging=false;function seek(e){const rect=board.getBoundingClientRect(),x=(e.clientX-rect.left)*700/rect.width;const first=350-(n-1)*45;p=Math.round((x-first)/90-(['ene','yne'].includes(mode)?.5:0));render();}board.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;dragging=true;board.setPointerCapture(e.pointerId);seek(e)});board.addEventListener('pointermove',e=>{if(dragging)seek(e)});board.addEventListener('pointerup',()=>dragging=false);board.addEventListener('pointercancel',()=>dragging=false);render();}
function mountChain(){if(!$('chain-game'))return;let n=5,edges=line(n),selected=null,showH=false,pinned=null,history=[],found=new Set();
function drawing(e,interactive){const pts=layout(n,e),a=adjacency(n,e);let s=e.map(([u,v])=>ln(pts[u],pts[v])).join('');pts.forEach((p,i)=>{const h=4-a[i].length,label=showH?'C'+(h?'H'+(h>1?sub(h):''):''):'C';const valid=selected!==null&&!!move(n,e,selected,i);s+=atom(...p,label,interactive?`data-carbon="${i}" tabindex="0" role="button" aria-label="Carbon ${i+1}, ${a[i].length===1?'end carbon':a[i].length+' carbon neighbours'}${valid?', valid destination':''}" class="si-carbon ${selected===i?'si-selected':''} ${valid?'si-target':''}"`:'');});return s;}
function render(){const name=chainName(n,edges);found.add(name);$('chain-board').innerHTML=drawing(edges,true);$('chain-name').textContent=name;$('chain-formula').textContent='C'+sub(n)+'H'+sub(2*n+2);$('chain-prompt').textContent=selected===null?'Select an end carbon.':'Select a highlighted carbon to reconnect it.';$('chain-undo').disabled=!history.length;$('chain-comparison').hidden=!pinned;$('chain-status').textContent=pinned?(key(n,edges)===key(n,pinned.edges)?'Same carbon skeleton as the pinned structure.':'Different chain isomer; same molecular formula.') :'';$('chain-found').textContent=`${found.size} / ${banks[n].length} chain isomers explored`;$('chain-gallery').innerHTML=banks[n].filter(x=>found.has(x[0])).map(([name],i)=>`<button type="button" data-name="${name}">${name}</button>`).join('');}
function select(i){const a=adjacency(n,edges);if(i===selected){selected=null;render();return;}if(selected===null){if(a[i].length!==1){$('chain-prompt').textContent='Choose an end carbon with one carbon neighbour.';return;}selected=i;}else{const next=move(n,edges,selected,i);if(!next){$('chain-prompt').textContent='Choose a highlighted destination; carbon can form four bonds.';return;}history.push(edges.map(e=>e.slice()));edges=next;selected=null;}render();}
$('chain-board').addEventListener('click',e=>{const el=e.target.closest('[data-carbon]');if(el)select(+el.dataset.carbon)});$('chain-board').addEventListener('keydown',e=>{const el=e.target.closest('[data-carbon]');if(el&&['Enter',' '].includes(e.key)){e.preventDefault();select(+el.dataset.carbon)}});$('chain-count').addEventListener('change',e=>{n=+e.target.value;edges=line(n);history=[];selected=null;pinned=null;found=new Set();render()});$('chain-undo').addEventListener('click',()=>{if(history.length)edges=history.pop();selected=null;render()});$('chain-reset').addEventListener('click',()=>{history.push(edges);edges=line(n);selected=null;render()});$('chain-h').addEventListener('click',()=>{showH=!showH;$('chain-h').setAttribute('aria-pressed',showH);if(pinned)$('chain-pinned-board').innerHTML=drawing(pinned.edges,false);render()});$('chain-pin').addEventListener('click',()=>{pinned={edges:edges.map(e=>e.slice()),name:chainName(n,edges)};$('chain-pinned-board').innerHTML=drawing(edges,false);$('chain-pinned-name').textContent=pinned.name;render()});$('chain-gallery').addEventListener('click',e=>{const b=e.target.closest('[data-name]');if(!b)return;history.push(edges);edges=banks[n].find(x=>x[0]===b.dataset.name)[1].map(x=>x.slice());selected=null;render()});render();}
mountPosition();mountChain();
})();
